/* Cognitive Care NER — video-structure override.
 * Uses the uploaded game videos as mechanic/UI references only; no exact questions/content are copied.
 */
(()=>{
'use strict';
if(window.CCNER_VIDEO_GAMES)return;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],shuffle=a=>[...a].sort(()=>Math.random()-.5),pick=a=>a[Math.floor(Math.random()*a.length)];
const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch(_){return f}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(_){}};
const H='ccner-history',L='ccner-video-levels',levels=Object.assign({sequence:1,sorting:1,pattern:1,difference:1,memory:1},read(L,{}));
const G={sequence:{title:'Sequence Memory',area:'MEMORY + ATTENTION',icon:'🔢',intro:'Watch the sequence, remember the order, then repeat it.',voice:'Watch the sequence carefully. Then repeat the same order.'},sorting:{title:'Around the House Sorting',area:'DAILY-LIFE RECOGNITION',icon:'🏠',intro:'Put each familiar object in the place where it belongs.',voice:'Look at each item and choose the place where it belongs.'},pattern:{title:'Pattern Recognition',area:'PATTERN RECOGNITION',icon:'🧩',intro:'Find the rule and choose what comes next.',voice:'Look for the pattern. What comes next?'},difference:{title:'Spot the Difference',area:'ATTENTION + OBJECT RECOGNITION',icon:'👀',intro:'Look carefully and find the one item that is different.',voice:'Look carefully. Which item is different?'},memory:{title:'Familiar Object Memory',area:'MEMORY',icon:'🧠',intro:'Remember familiar objects, then identify one you saw.',voice:'Look carefully and remember these familiar objects.'}};
const house=[['🌅','Alarm clock','Bedroom'],['🪥','Toothbrush','Bathroom'],['☕','Tea cup','Kitchen'],['💊','Medicine box','Medicine shelf'],['📖','Book','Living room'],['🧹','Broom','Utility area'],['👟','Shoes','Shoe rack'],['🧺','Basket','Storage area']];
const objs=[['☕','Tea cup'],['🥄','Spoon'],['📖','Book'],['💊','Medicine box'],['💧','Water bottle'],['🍚','Rice bowl'],['🧢','Cap'],['🌂','Umbrella'],['🧴','Bottle'],['🧺','Basket']];
const local=[['🍵','Tea'],['🎋','Bamboo'],['🧺','Bamboo basket'],['🍚','Rice'],['🥥','Coconut'],['🧣','Shawl'],['🪔','Earthen lamp'],['🍃','Betel leaf']];
const patterns=[{v:['●','○','●','○'],a:'●',c:['●','○','■','▲']},{v:['▲','■','▲','■'],a:'▲',c:['▲','■','●','◆']},{v:['1','3','7','15','31'],a:'63',c:['55','47','63','62']},{v:['2','5','10','17','26'],a:'37',c:['34','36','37','40']},{v:['●','■','●','■','●'],a:'■',c:['●','■','▲','◆']}];
const state={active:false,i:0,order:[],round:0,current:null,results:[]};
const css=`.p8v-intro{padding:24px;text-align:center;background:rgba(255,255,255,.9);border:1px solid #e5ddd4;border-radius:22px}.p8v-icon{font-size:44px}.p8v-intro h3{font-size:26px;margin:6px 0}.p8v-intro p{font-size:17px;line-height:1.5}.p8v-tags{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:16px 0}.p8v-tags span{padding:8px 12px;border-radius:999px;background:#f3eee7}.p8v-question{text-align:center;font-size:21px;font-weight:800;margin:12px 0 18px}.p8v-sequence,.p8v-colours{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}.p8v-sequence span,.p8v-colour{width:64px;height:64px;border-radius:14px;border:0;box-shadow:0 4px 10px #0002}.seq-red{background:#d95c5c}.seq-blue{background:#5d7fd7}.seq-green{background:#65a76b}.seq-yellow{background:#e0ba4c}.seq-purple{background:#8d68bd}.p8v-colour{cursor:pointer}.p8v-colour:disabled{opacity:.35}.p8v-picked,.p8v-muted{color:#6b625a;text-align:center;margin:12px}.p8v-sort-list{display:grid;gap:12px}.p8v-sort-row{padding:14px;border:1px solid #e4ddd5;border-radius:16px;background:#fbf8f3}.p8v-item{display:flex;gap:10px;align-items:center;font-size:18px;margin-bottom:10px}.p8v-item span{font-size:28px}.p8v-cat-wrap{display:flex;gap:7px;flex-wrap:wrap}.p8v-cat,.p8v-answer{min-height:48px;padding:9px 14px;border:1px solid #d8d0c7;border-radius:12px;background:#fff;cursor:pointer;font-size:15px}.p8v-cat.selected{background:#e7f3e9;outline:3px solid #77a77e55}.p8v-pattern{display:flex;gap:10px;justify-content:center;align-items:center;flex-wrap:wrap;font-size:28px;margin:20px}.p8v-pattern span{min-width:48px;padding:11px 8px;text-align:center;border-radius:12px;background:#f1eee9}.p8v-pattern .missing{background:#e7f3e9}.p8v-answer-list{display:grid;gap:10px;max-width:600px;margin:auto}.p8v-answer{width:100%;font-weight:700}.p8v-diff-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;max-width:520px;margin:auto}.p8v-diff{min-height:82px;font-size:36px;border:1px solid #d8d0c7;border-radius:16px;background:#fff;cursor:pointer}.p8v-memory{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:12px}.p8v-memory>div{display:flex;flex-direction:column;align-items:center;gap:7px;padding:16px 8px;border-radius:15px;background:#f6f1ea}.p8v-memory span{font-size:40px}@media(max-width:600px){.p8v-diff-grid{grid-template-columns:repeat(2,1fr)}.p8v-cat{font-size:13px;padding:8px 10px}.p8v-question{font-size:19px}}`;
const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);
function speak(t){if(!('speechSynthesis'in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang=localStorage.getItem('ccner-p1-language')||'en-IN';u.rate=.9;speechSynthesis.speak(u)}catch(_){}}
function level(k){return Math.max(1,Math.min(3,Number(levels[k]||1)))}function label(n){return ['','Easy','Medium','Hard'][n]}
function adapt(k,s){let n=level(k);if(s>=.8)n=Math.min(3,n+1);else if(s<=.4)n=Math.max(1,n-1);levels[k]=n;write(L,levels)}
function showGame(){ $$('.view').forEach(v=>v.hidden=true);$('#gameView').hidden=false }
function start(){if(state.active)return;state.active=true;state.i=0;state.round=0;state.results=[];state.order=shuffle(['sequence','sorting','pattern','difference','memory']);showGame();load()}
function load(){const k=state.order[state.i],g=G[k],n=level(k);state.current={k,level:n,correct:0,time:0,live:false};state.round=0;$('#gameCategory').textContent=g.area;$('#gameTitle').textContent=g.title;$('#gameCounter').textContent=`${state.i+1} of 5`;$('#gamePrompt').textContent=g.intro;$('#gameMomoText').textContent=`${label(n)} · Momo will guide you step by step.`;$('#gameFeedback').textContent='';const b=$('#progressBar');if(b)b.style.width=`${state.i/5*100}%`;intro(g,n);speak(g.voice)}
function intro(g,n){const a=$('#gameArea');a.innerHTML=`<section class="p8v-intro"><div class="p8v-icon">${g.icon}</div><h3>${esc(g.title)}</h3><p><strong>What it trains:</strong> ${esc(g.area.toLowerCase())}</p><p>${esc(g.intro)}</p><div class="p8v-tags"><span>🎚️ ${label(n)}</span><span>🔁 3 rounds</span><span>🧓 Training only · not diagnosis</span></div><button class="p8-primary" id="p8vStart">▶ Start game</button></section>`;$('#p8vStart').onclick=round}
function round(){if(!state.active||state.current.live)return;state.current.live=true;state.round++;$('#gameFeedback').textContent=`Round ${state.round} of 3`;const k=state.current.k;if(k==='sequence')sequence();else if(k==='sorting')sorting();else if(k==='pattern')pattern();else if(k==='difference')difference();else memory()}
function done(ok,ms){if(!state.current.live)return;state.current.live=false;state.current.correct+=ok?1:0;state.current.time+=ms;$('#gameFeedback').textContent=ok?'✓ Correct — well done!':'Good try. Let’s continue.';if(state.round<3)return setTimeout(round,900);const s=state.current.correct/3;adapt(state.current.k,s);state.results.push({key:state.current.k,name:G[state.current.k].title,area:G[state.current.k].area,level:state.current.level,score:Math.round(s*100),accuracy:s,correct:state.current.correct,attempts:3,avgResponse:state.current.time/3,completed:true});setTimeout(()=>{if(state.i<4){state.i++;load()}else finish()},900)}
function sequence(){const n=level('sequence')===1?3:level('sequence')===2?4:5,seq=shuffle(['red','blue','green','yellow','purple']).slice(0,n),started=performance.now(),a=$('#gameArea');a.innerHTML=`<div class="p8v-question">Watch the sequence</div><div class="p8v-sequence">${seq.map(c=>`<span class="seq-${c}"></span>`).join('')}</div><p class="p8v-muted">Remember the order.</p>`;setTimeout(()=>{if(!state.current.live)return;let chosen=[];a.innerHTML=`<div class="p8v-question">Repeat the sequence</div><div class="p8v-picked" id="p8vPicked">Choose the first colour.</div><div class="p8v-colours">${['red','blue','green','yellow','purple'].map(c=>`<button class="p8v-colour seq-${c}" data-c="${c}" aria-label="${c}"></button>`).join('')}</div>`;$$('.p8v-colour').forEach(b=>b.onclick=()=>{chosen.push(b.dataset.c);b.disabled=true;$('#p8vPicked').textContent=`${chosen.length} selected`;if(chosen.length===seq.length)done(chosen.every((x,i)=>x===seq[i]),performance.now()-started)})},Math.max(2200,4700-level('sequence')*500))}
function sorting(){const count=level('sorting')===1?4:level('sorting')===2?5:6,items=shuffle(house).slice(0,count),started=performance.now(),cats=['Bedroom','Bathroom','Kitchen','Medicine shelf','Living room','Utility area','Shoe rack','Storage area'];const a=$('#gameArea');a.innerHTML=`<div class="p8v-question">Where do they belong?</div><div class="p8v-sort-list">${items.map((x,i)=>`<div class="p8v-sort-row"><div class="p8v-item"><span>${x[0]}</span><strong>${esc(x[1])}</strong></div><div class="p8v-cat-wrap">${cats.slice(0,level('sorting')===3?8:5).map(c=>`<button class="p8v-cat" data-i="${i}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div></div>`).join('')}</div><button id="p8vCheck" class="p8-primary">✓ Check answers</button>`;const ans={};$$('.p8v-cat').forEach(b=>b.onclick=()=>{ans[b.dataset.i]=b.dataset.cat;$$(`.p8v-cat[data-i="${b.dataset.i}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});$('#p8vCheck').onclick=()=>{if(Object.keys(ans).length<items.length)return;done(items.every((x,i)=>ans[i]===x[2]),performance.now()-started)}}
function pattern(){const p=pick(patterns),started=performance.now(),a=$('#gameArea');a.innerHTML=`<div class="p8v-question">What comes next in the pattern?</div><div class="p8v-pattern">${p.v.map(x=>`<span>${esc(x)}</span>`).join('')}<span class="missing">?</span></div><div class="p8v-answer-list">${shuffle(p.c).map(x=>`<button class="p8v-answer" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>`;$$('.p8v-answer').forEach(b=>b.onclick=()=>done(b.dataset.v===p.a,performance.now()-started))}
function difference(){const sets=[['🐘','🐘','🐘','🦌','🐘','🐘'],['🍎','🍎','🍎','🍐','🍎','🍎'],['☕','☕','🥣','☕','☕','☕'],['🧢','🧢','🧢','🎩','🧢','🧢'],['🐟','🐟','🐠','🐟','🐟','🐟']],base=pick(sets),correct=base.findIndex(x=>base.filter(y=>y===x).length===1),started=performance.now(),a=$('#gameArea');a.innerHTML=`<div class="p8v-question">Which item is different?</div><div class="p8v-diff-grid">${base.map((x,i)=>`<button class="p8v-diff" data-i="${i}">${x}</button>`).join('')}</div><p class="p8v-muted">Look carefully. Only one item is different.</p>`;$$('.p8v-diff').forEach(b=>b.onclick=()=>done(Number(b.dataset.i)===correct,performance.now()-started))}
function memory(){const n=level('memory')===1?3:level('memory')===2?4:5,sec=level('memory')===1?8:level('memory')===2?7:6,all=shuffle([...objs,...local]),items=all.slice(0,n),target=pick(items),started=performance.now(),a=$('#gameArea');a.innerHTML=`<div class="p8v-question">Remember these objects · ${sec} seconds</div><div class="p8v-memory">${items.map(x=>`<div><span>${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div>`;setTimeout(()=>{if(!state.current.live)return;const choices=shuffle([target,...shuffle(all.filter(x=>!items.includes(x))).slice(0,3)]);a.innerHTML=`<div class="p8v-question">Which object did you see?</div><div class="p8v-answer-list">${choices.map(x=>`<button class="p8v-answer" data-v="${esc(x[1])}"><span>${x[0]}</span> ${esc(x[1])}</button>`).join('')}</div>`;$$('.p8v-answer').forEach(b=>b.onclick=()=>done(b.dataset.v===target[1],performance.now()-started))},sec*1000)}
function finish(){state.active=false;const total=state.results.reduce((a,r)=>a+r.correct,0),s={date:new Date().toISOString(),score:Math.round(total/15*100),accuracy:total/15,avgTime:state.results.reduce((a,r)=>a+r.avgResponse,0)/5,results:state.results};const h=read(H,[]);h.push(s);write(H,h.slice(-30));$$('.view').forEach(v=>v.hidden=true);$('#resultsView').hidden=false;$('#overallScore').textContent=s.score+'%';$('#overallAccuracy').textContent=s.score+'%';$('#gamesCompleted').textContent='5 / 5';$('#avgTime').textContent=s.avgTime.toFixed(1)+'s';$('#trendBadge').textContent='Training session complete';$('#resultRows').innerHTML=state.results.map(r=>`<div class="p8-result"><div><strong>${esc(r.name)}</strong><div class="p8v-muted">${esc(r.area)} · ${label(r.level)} · ${r.correct}/${r.attempts} correct · ${r.avgResponse.toFixed(1)}s</div></div><strong>${r.score}%</strong></div>`).join('');speak('You completed all five games. Well done.')}
window.CCNER_VIDEO_GAMES={startSession:start,order:()=>state.order.slice(),levels:()=>({...levels})};
if(window.CCNER_PHASE8)window.CCNER_PHASE8.startSession=start;
})();